        "RegionEncoded",
        nameof(CustomerData.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression());

var rowCount = (int)data.GetColumn<float>("Age").Count();

// Use train/test split when the dataset is large enough; otherwise train on all data
IDataView trainData, testData;
if (rowCount >= 20)
{
    var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2);
    trainData = split.TrainSet;
    testData = split.TestSet;
}
else
{
    Console.WriteLine($"Small dataset ({rowCount} rows) — training on all data; add more rows for proper evaluation.");
    trainData = data;
    testData = data;
}

var model = pipeline.Fit(trainData);

// Evaluate
var predictions = model.Transform(testData);
