using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.Extensions.ML;

var builder = WebApplication.CreateBuilder(args);

// Train and save the model at startup
var modelPath = Path.Combine(AppContext.BaseDirectory, "churn-model.zip");
TrainModel(Path.Combine("Data", "customers.csv"), modelPath);

// Register pooled prediction engine (thread-safe for web apps)
builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapGet("/", () => "Churn Predictor API — POST /predict with customer data");

app.MapPost("/predict", (PredictionEnginePool<CustomerData, ChurnPrediction> pool, CustomerData input) =>
{
    var prediction = pool.Predict(input);
    return Results.Ok(new
    {
        WillChurn = prediction.PredictedLabel,
        Probability = prediction.Probability,
        Score = prediction.Score,
    });
});

app.Run();

static void TrainModel(string dataPath, string modelPath)
{
    var mlContext = new MLContext(seed: 42);

    var data = mlContext.Data.LoadFromTextFile<CustomerData>(
        dataPath, hasHeader: true, separatorChar: ',');

    // Map "Yes"/"No" label to bool, one-hot encode Region, concatenate features
    var pipeline = mlContext.Transforms.CustomMapping<CustomerData, ChurnLabel>(
            (input, output) => output.Label = string.Equals(input.Churned, "Yes", StringComparison.OrdinalIgnoreCase),
            contractName: "ChurnMapping")
        .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
        .Append(mlContext.Transforms.Concatenate("Features",
            nameof(CustomerData.Age),
            nameof(CustomerData.Income),
            "RegionEncoded",
            nameof(CustomerData.PurchaseHistory)))
        .Append(mlContext.Transforms.NormalizeMinMax("Features"))
        .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression());

    var rowCount = (int)data.GetColumn<float>("Age").Count();

    // Use train/test split when the dataset is large enough; otherwise train on all data
    IDataView trainData, testData;
    if (rowCount >= 20)
    {
        var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2);
        trainData = split.TrainSet;
        testData = split.TestSet;
    }
    else
    {
        Console.WriteLine($"Small dataset ({rowCount} rows) — training on all data; add more rows for proper evaluation.");
        trainData = data;
        testData = data;
    }

    var model = pipeline.Fit(trainData);

    // Evaluate
    var predictions = model.Transform(testData);
    var metrics = mlContext.BinaryClassification.Evaluate(predictions);
    Console.WriteLine($"Model metrics — AUC: {metrics.AreaUnderRocCurve:F4}, " +
                      $"Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");

    mlContext.Model.Save(model, data.Schema, modelPath);
    Console.WriteLine($"Model saved to {modelPath}");
}

